// Original static finishing-work props. Age resets when a zone grows a level;
// the cue indicates recent development, not a separate construction simulation.
export const recentDevelopment=t=>['residential','commercial','industrial'].includes(t.type)&&t.industry!=='farm'&&t.level>0&&t.age<2&&!t.historicalLevel&&!t.abandonedLevel&&!t.fire&&!t.rubble&&!t.radiation;
export function constructionEdges(renderer,t,width=1,height=1){const u=renderer.unit,p=renderer.project(t.x,t.y),origin=renderer.transform(t.x,t.y),point=(dx,dy)=>{const q=renderer.transform(t.x+dx,t.y+dy);return{x:p.x+((q[0]-origin[0])-(q[1]-origin[1]))*u,y:p.y+u/2+((q[0]-origin[0])+(q[1]-origin[1]))*u/2};},corners=[point(-.4,-.4),point(width-.6,-.4),point(width-.6,height-.6),point(-.4,height-.6)];let front=0;for(let i=1;i<4;i++)if(corners[i].y>corners[front].y)front=i;return [corners[(front+3)%4],corners[(front+1)%4]].map(other=>{const a=corners[front],at=f=>({x:a.x+(other.x-a.x)*f,y:a.y+(other.y-a.y)*f});return{a:at(.12),b:at(Math.min(.8,.12+.6/Math.max(width,height)))};});}
export function drawRecentConstruction(renderer,t,lot){if(renderer.layer!=='city'||renderer.preferences?.constructionDetails===false||!recentDevelopment(t))return;const c=renderer.ctx,u=renderer.unit,edges=constructionEdges(renderer,t,lot?.width||1,lot?.height||1);c.save();
 const poly=(points,color)=>{c.fillStyle=color;c.beginPath();c.moveTo(points[0].x,points[0].y);for(const p of points.slice(1))c.lineTo(p.x,p.y);c.closePath();c.fill();};
 for(const {a,b}of edges){const lift=p=>({x:p.x,y:p.y-u*.2}),low=p=>({x:p.x,y:p.y-u*.09});c.strokeStyle='#665b40';c.lineWidth=Math.max(1,u*.045);for(const p of[a,b]){c.beginPath();c.moveTo(p.x,p.y);c.lineTo(p.x,p.y-u*.24);c.stroke();}poly([lift(a),lift(b),low(b),low(a)],'#f3bc55');poly([lift(a),lift(b),{x:b.x,y:b.y-u*.23},{x:a.x,y:a.y-u*.23}],'#ffe3a2');for(let i=0;i<3;i++){const start=(i+.15)/3,end=(i+.5)/3,at=(f,h)=>({x:a.x+(b.x-a.x)*f,y:a.y+(b.y-a.y)*f-u*h});poly([at(start,.2),at(end,.2),at(end,.09),at(start,.09)],'#555341');}}
 c.restore();}
export function recentConstructionNote(t){return recentDevelopment(t)?'<p>Recent development: finishing-work barriers mark the first two simulation months after this building grew. They do not delay occupancy or service.</p>':'';}
